#!/bin/sh
set -eu

echo "Fed-up bootstrapper"
if ! command -v python3 >/dev/null 2>&1; then
  echo "python3 is required" >&2
  exit 1
fi

TMPDIR=$(mktemp -d)
trap 'rm -rf "$TMPDIR"' EXIT INT TERM

mkdir -p "$TMPDIR/fedup_tui"
python3 - "$TMPDIR/fedup_tui" "" <<'PY'
import base64, json, sys, os
data = base64.b64decode("")
files = json.loads(data)
base = sys.argv[1]
for rel, content in files.items():
    path = os.path.join(base, rel)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
data_b64 = sys.argv[2] if len(sys.argv) > 2 else ''
if data_b64:
    with open(os.path.join(os.path.dirname(base), 'data.json'), 'w', encoding='utf-8') as f:
        f.write(base64.b64decode(data_b64).decode())
PY

cd "$TMPDIR"
python3 -m fedup_tui --config "$TMPDIR/data.json" "$@"
